/**
 * The Better Auth tables, generated by Better Auth itself from Podbay's configuration.
 *
 *   node scripts/auth-ddl.ts            print the DDL for an empty database
 *   node scripts/auth-ddl.ts --check    fail when the auth migrations no longer produce the
 *                                       schema the configuration needs
 *
 * The tables are never written by hand. After a configuration change that adds a table or a
 * column, run with --delta to get the statements for a new migration file.
 *
 *   node scripts/auth-ddl.ts --delta    print what a new migration must add
 */
import { readdirSync, readFileSync } from "node:fs";
import { DatabaseSync } from "node:sqlite";
import { getMigrations } from "better-auth/db/migration";
import { authOptions } from "../workers/auth/options.ts";

const MIGRATIONS_DIR = "migrations";

function options(database: DatabaseSync) {
	return authOptions({ database, baseURL: "http://localhost", secret: "x".repeat(32) });
}

/** The statements Better Auth wants to run against `database` to reach its schema. */
export async function pendingDdl(database: DatabaseSync): Promise<string> {
	const { compileMigrations } = await getMigrations(options(database));
	const ddl = (await compileMigrations()).trim();
	// With nothing to do Better Auth returns a lone statement terminator.
	return ddl.replace(/;/g, "").trim() === "" ? "" : ddl;
}

/** A database with every checked-in migration applied, in file-name order. */
export function migratedDatabase(): DatabaseSync {
	const database = new DatabaseSync(":memory:");
	const files = readdirSync(MIGRATIONS_DIR)
		.filter((f) => f.endsWith(".sql"))
		.sort();
	for (const file of files) database.exec(readFileSync(`${MIGRATIONS_DIR}/${file}`, "utf8"));
	return database;
}

if (import.meta.url === `file://${process.argv[1]}`) {
	const argv = process.argv.slice(2);
	if (argv.includes("--check") || argv.includes("--delta")) {
		const delta = await pendingDdl(migratedDatabase());
		if (argv.includes("--delta")) {
			process.stdout.write(delta === "" ? "-- nothing to add\n" : `${delta}\n`);
		} else if (delta !== "") {
			process.stderr.write(
				`auth-ddl: the migrations do not produce Better Auth's schema. A new migration must add:\n${delta}\n`,
			);
			process.exitCode = 1;
		} else {
			process.stdout.write("auth-ddl ok\n");
		}
	} else {
		process.stdout.write(`${await pendingDdl(new DatabaseSync(":memory:"))}\n`);
	}
}
